# shellcheck disable=all
# This is a shell completion script auto-generated by https://github.com/urfave/cli for bash.

# macOS still ships Bash 3, where bash-completion may not provide
# _init_completion. This is a minimal compatible fallback.
__otter_init_completion() {
  COMPREPLY=()
  if declare -F _comp_initialize >/dev/null 2>&1; then
    _comp_initialize "$@"
  else
    _get_comp_words_by_ref "$@" cur prev words cword
  fi
}

# Keep Bash 3 compatibility: associative arrays require Bash 4+, so
# descriptions are looked up via parallel indexed arrays.
__otter_find_description_for() {
  local candidate="$1"
  local i

  for i in "${!__cli_completion_tokens[@]}"; do
    if [[ "${__cli_completion_tokens[i]}" == "${candidate}" ]]; then
      printf '%s' "${__cli_completion_descriptions[i]}"
      return 0
    fi
  done

  return 1
}

__otter_bash_autocomplete() {
  local words=("${COMP_WORDS[@]}")

  if [[ "${words[0]}" != "source" ]]; then
    local cur opts
    local cword="${COMP_CWORD}"

    COMPREPLY=()
    cur="${words[$cword]}"

    __otter_init_completion -n "=:" || return

    # Build the completion request as an argv array. Flattening into a
    # string and eval-ing it re-parses quoted words as shell syntax, so a
    # container name like "x; touch /tmp/pwned" would execute on TAB.
    local -a request=("${words[@]:0:${cword}}")
    # The typed first word can be an alias (`alias o=otter`) or a wrapper
    # (`sudo otter ...`). Normalize it to the real command before executing
    # the request; never treat arbitrary typed words as an executable.
    if [[ ${#request[@]} -gt 1 && ( "${request[1]}" == "otter" || "${request[1]}" == *"/otter" ) ]]; then
      request=("${request[@]:1}")
    elif [[ ${#request[@]} -eq 0 || ( "${request[0]}" != "otter" && "${request[0]}" != *"/otter" ) ]]; then
      request=("otter" "${request[@]:1}")
    fi
    [[ "${cur}" == -* ]] && request+=("${cur}")
    request+=("--generate-shell-completion")
    opts=$("${request[@]}" 2>/dev/null)

    # Completion output lines use "token:description" format.
    # Keep token/description in parallel arrays for Bash 3 compatibility.
    __cli_completion_tokens=()
    __cli_completion_descriptions=()

    local line
    local longest=0
    while IFS=$'\n' read -r line; do
      local token="${line}"
      local description=""
      
      if [[ "${line}" == *:* ]]; then
        token="${line%%:*}"
        description="${line#*:}"
      fi

      if [[ -z "${token}" ]]; then
        continue
      fi

      __cli_completion_tokens+=("${token}")
      __cli_completion_descriptions+=("${description}")
      (( ${#token} > longest )) && longest=${#token}
    done <<< "${opts}"

    local matches=( $(compgen -W "${__cli_completion_tokens[*]}" -- "${cur}") )

    # COMP_TYPE=63 means Bash is listing matches (usually on second TAB).
    if [[ "${COMP_TYPE:-}" == "63" && ${#matches[@]} -gt 0 ]]; then
      local listed=()
      local candidate
      for candidate in "${matches[@]}"; do
        local desc="$(__otter_find_description_for "${candidate}")"

        if [[ -n "${desc}" ]]; then
          local padded="$(printf '%-*s' "${longest}" "${candidate}")"
          listed+=("${padded}  -- ${desc}")
        else
          listed+=("${candidate}")
        fi
      done
      COMPREPLY=("${listed[@]}")
    else
      COMPREPLY=("${matches[@]}")
    fi

    return 0
  fi
}

complete -o bashdefault -o default -F __otter_bash_autocomplete otter
